-- ============================================================================
-- SECTION 1: SHARED TRIGGER FUNCTION
-- ============================================================================

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';


-- ============================================================================
-- SECTION 2: CORE TABLES (users, courses, modules, students, enrollments)
-- ============================================================================

-- users: admin / faculty / accounting rows all live here, keyed by role.
CREATE TABLE IF NOT EXISTS users (
  id VARCHAR(255) PRIMARY KEY,
  username VARCHAR(255) UNIQUE NOT NULL,
  password VARCHAR(255) NOT NULL,          -- PLAIN TEXT in current app; see service-catalog.md
  role user_role NOT NULL,
  department VARCHAR(255),                  -- added by migrate-add-departments*
  name VARCHAR(255) NOT NULL,
  email VARCHAR(255) UNIQUE NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);
CREATE INDEX IF NOT EXISTS idx_users_department ON users(department);

DROP TRIGGER IF EXISTS update_users_updated_at ON users;
CREATE TRIGGER update_users_updated_at BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


-- courses (must precede students: students.course_id FKs into it)
CREATE TABLE IF NOT EXISTS courses (
  id VARCHAR(255) PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  description TEXT,
  instructor VARCHAR(255) NOT NULL,
  department VARCHAR(255),                  -- added by migrate-add-departments*
  start_date DATE,
  end_date DATE,
  total_years INT,                          -- added by migrate-add-total-years.sql
  capacity INT DEFAULT 30,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_courses_instructor ON courses(instructor);
CREATE INDEX IF NOT EXISTS idx_courses_department ON courses(department);

DROP TRIGGER IF EXISTS update_courses_updated_at ON courses;
CREATE TRIGGER update_courses_updated_at BEFORE UPDATE ON courses
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


-- course_modules
CREATE TABLE IF NOT EXISTS course_modules (
  id VARCHAR(255) PRIMARY KEY,
  course_id VARCHAR(255) NOT NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT,
  duration_hours DECIMAL(5,2),
  order_index INT DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_course_modules_course ON course_modules(course_id);
CREATE INDEX IF NOT EXISTS idx_course_modules_order ON course_modules(order_index);

DROP TRIGGER IF EXISTS update_course_modules_updated_at ON course_modules;
CREATE TRIGGER update_course_modules_updated_at BEFORE UPDATE ON course_modules
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


-- module_materials
CREATE TABLE IF NOT EXISTS module_materials (
  id VARCHAR(255) PRIMARY KEY,
  module_id VARCHAR(255) NOT NULL,
  title VARCHAR(255) NOT NULL,
  file_name VARCHAR(255),
  file_path VARCHAR(500),
  file_size BIGINT,
  file_type VARCHAR(100),
  uploaded_by VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (module_id) REFERENCES course_modules(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_module_materials_module ON module_materials(module_id);


-- students: student/parent-facing account + admissions/fee state.
CREATE TABLE IF NOT EXISTS students (
  id VARCHAR(255) PRIMARY KEY,
  first_name VARCHAR(255) NOT NULL,
  last_name VARCHAR(255) NOT NULL,
  email VARCHAR(255) UNIQUE NOT NULL,
  username VARCHAR(255) UNIQUE NOT NULL,
  password VARCHAR(255) NOT NULL,           -- PLAIN TEXT in current app; see service-catalog.md
  phone VARCHAR(50),
  date_of_birth DATE,
  address TEXT,
  city VARCHAR(255),
  state VARCHAR(255),
  country VARCHAR(255),
  postal_code VARCHAR(20),
  course_id VARCHAR(255),
  year VARCHAR(50),
  cohort VARCHAR(255),
  batch_timing batch_timing_enum,           -- added by migrate-add-attendance.sql
  class_schedule schedule_type_enum,        -- added by migrate-add-attendance.sql
  status student_status DEFAULT 'active',
  application_status application_status_enum DEFAULT 'pending', -- migrate-add-application-status.sql
  course_fee DECIMAL(10,2),
  payment_plan payment_plan_type,
  payment_plan_details TEXT,
  fee_due_date DATE,                        -- added by migrate-add-fee-due-date.js
  send_reminder BOOLEAN DEFAULT TRUE,        -- added by migrate-add-fee-due-date.js
  offer_letter_sent BOOLEAN DEFAULT FALSE,
  offer_letter_sent_at TIMESTAMP,
  guardian_name VARCHAR(255),
  guardian_email VARCHAR(255),
  guardian_phone VARCHAR(50),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_students_email ON students(email);
CREATE INDEX IF NOT EXISTS idx_students_course ON students(course_id);
CREATE INDEX IF NOT EXISTS idx_students_status ON students(status);
CREATE INDEX IF NOT EXISTS idx_students_application_status ON students(application_status);
CREATE INDEX IF NOT EXISTS idx_students_fee_due_date ON students(fee_due_date);

DROP TRIGGER IF EXISTS update_students_updated_at ON students;
CREATE TRIGGER update_students_updated_at BEFORE UPDATE ON students
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


-- course_tags (many-to-many-ish tag list)
CREATE TABLE IF NOT EXISTS course_tags (
  id SERIAL PRIMARY KEY,
  course_id VARCHAR(255) NOT NULL,
  tag VARCHAR(100) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,
  UNIQUE (course_id, tag)
);
CREATE INDEX IF NOT EXISTS idx_course_tags_tag ON course_tags(tag);


-- course_enrollments (many-to-many: courses <-> students)
CREATE TABLE IF NOT EXISTS course_enrollments (
  id SERIAL PRIMARY KEY,
  course_id VARCHAR(255) NOT NULL,
  student_id VARCHAR(255) NOT NULL,
  enrolled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  UNIQUE (course_id, student_id)
);
CREATE INDEX IF NOT EXISTS idx_course_enrollments_student ON course_enrollments(student_id);


-- ============================================================================
-- SECTION 3: ASSIGNMENTS
-- ============================================================================

CREATE TABLE IF NOT EXISTS assignments (
  id VARCHAR(255) PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  course_id VARCHAR(255) NOT NULL,
  description TEXT,
  due_date TIMESTAMP,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (course_id) REFERENCES courses(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_assignments_course ON assignments(course_id);
CREATE INDEX IF NOT EXISTS idx_assignments_due_date ON assignments(due_date);

DROP TRIGGER IF EXISTS update_assignments_updated_at ON assignments;
CREATE TRIGGER update_assignments_updated_at BEFORE UPDATE ON assignments
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


CREATE TABLE IF NOT EXISTS assignment_submissions (
  id VARCHAR(255) PRIMARY KEY,
  assignment_id VARCHAR(255) NOT NULL,
  student_id VARCHAR(255) NOT NULL,
  notes TEXT,
  artifact_name VARCHAR(255),
  grade DECIMAL(5,2),                       -- migrate-add-assignment-grades.sql
  feedback TEXT,                            -- migrate-add-assignment-grades.sql
  graded_at TIMESTAMP,                      -- migrate-add-assignment-grades.sql
  graded_by VARCHAR(255),                   -- migrate-add-assignment-grades.sql
  submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (assignment_id) REFERENCES assignments(id) ON DELETE CASCADE,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_assignment_submissions_assignment ON assignment_submissions(assignment_id);
CREATE INDEX IF NOT EXISTS idx_assignment_submissions_student ON assignment_submissions(student_id);
CREATE INDEX IF NOT EXISTS idx_assignment_submissions_submitted_at ON assignment_submissions(submitted_at);
CREATE INDEX IF NOT EXISTS idx_assignment_submissions_grade ON assignment_submissions(grade);


-- ============================================================================
-- SECTION 4: CHAT (group + private)
-- ============================================================================

CREATE TABLE IF NOT EXISTS chat_groups (
  id VARCHAR(255) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_chat_groups_name ON chat_groups(name);

DROP TRIGGER IF EXISTS update_chat_groups_updated_at ON chat_groups;
CREATE TRIGGER update_chat_groups_updated_at BEFORE UPDATE ON chat_groups
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


CREATE TABLE IF NOT EXISTS chat_group_members (
  id SERIAL PRIMARY KEY,
  group_id VARCHAR(255) NOT NULL,
  user_id VARCHAR(255) NOT NULL,            -- polymorphic: users.id or students.id
  joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (group_id) REFERENCES chat_groups(id) ON DELETE CASCADE,
  UNIQUE (group_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_chat_group_members_user ON chat_group_members(user_id);


CREATE TABLE IF NOT EXISTS chat_group_messages (
  id VARCHAR(255) PRIMARY KEY,
  group_id VARCHAR(255) NOT NULL,
  user_id VARCHAR(255) NOT NULL,            -- polymorphic
  author VARCHAR(255) NOT NULL,
  message TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (group_id) REFERENCES chat_groups(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_chat_group_messages_group ON chat_group_messages(group_id);
CREATE INDEX IF NOT EXISTS idx_chat_group_messages_created_at ON chat_group_messages(created_at);


CREATE TABLE IF NOT EXISTS private_chat_threads (
  id VARCHAR(255) PRIMARY KEY,
  participant1_id VARCHAR(255) NOT NULL,    -- polymorphic
  participant2_id VARCHAR(255) NOT NULL,    -- polymorphic
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (participant1_id, participant2_id)
);
CREATE INDEX IF NOT EXISTS idx_private_chat_threads_participant1 ON private_chat_threads(participant1_id);
CREATE INDEX IF NOT EXISTS idx_private_chat_threads_participant2 ON private_chat_threads(participant2_id);

DROP TRIGGER IF EXISTS update_private_chat_threads_updated_at ON private_chat_threads;
CREATE TRIGGER update_private_chat_threads_updated_at BEFORE UPDATE ON private_chat_threads
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


CREATE TABLE IF NOT EXISTS private_chat_messages (
  id VARCHAR(255) PRIMARY KEY,
  thread_id VARCHAR(255) NOT NULL,
  user_id VARCHAR(255) NOT NULL,            -- polymorphic
  author VARCHAR(255) NOT NULL,
  message TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (thread_id) REFERENCES private_chat_threads(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_private_chat_messages_thread ON private_chat_messages(thread_id);
CREATE INDEX IF NOT EXISTS idx_private_chat_messages_created_at ON private_chat_messages(created_at);


-- ============================================================================
-- SECTION 5: CALENDAR
-- ============================================================================

CREATE TABLE IF NOT EXISTS calendar_events (
  id VARCHAR(255) PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  description TEXT,
  event_date DATE NOT NULL,
  event_time TIME,
  assignment_id VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (assignment_id) REFERENCES assignments(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_calendar_events_event_date ON calendar_events(event_date);
CREATE INDEX IF NOT EXISTS idx_calendar_events_assignment ON calendar_events(assignment_id);

DROP TRIGGER IF EXISTS update_calendar_events_updated_at ON calendar_events;
CREATE TRIGGER update_calendar_events_updated_at BEFORE UPDATE ON calendar_events
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


-- ============================================================================
-- SECTION 6: ACCOUNTING (tasks, salaries, salary payments, student payments)
-- ============================================================================

CREATE TABLE IF NOT EXISTS accounting_tasks (
  id VARCHAR(255) PRIMARY KEY,
  student_id VARCHAR(255) NOT NULL,
  task_type task_type_enum DEFAULT 'fee_setup',
  status task_status_enum DEFAULT 'pending',
  priority priority_enum DEFAULT 'medium',
  assigned_to VARCHAR(255),
  title VARCHAR(255) NOT NULL,
  description TEXT,
  student_data JSONB,
  fee_details JSONB,
  notes TEXT,
  admin_remarks TEXT,                       -- migrate-add-application-status.sql
  accounting_remarks TEXT,                  -- migrate-add-application-status.sql
  completed_at TIMESTAMP,
  reviewed_at TIMESTAMP,                    -- migrate-add-application-status.sql
  completed_by VARCHAR(255),
  reviewed_by VARCHAR(255),                 -- migrate-add-application-status.sql
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE,
  FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_accounting_tasks_student ON accounting_tasks(student_id);
CREATE INDEX IF NOT EXISTS idx_accounting_tasks_status ON accounting_tasks(status);
CREATE INDEX IF NOT EXISTS idx_accounting_tasks_assigned_to ON accounting_tasks(assigned_to);
CREATE INDEX IF NOT EXISTS idx_accounting_tasks_task_type ON accounting_tasks(task_type);
CREATE INDEX IF NOT EXISTS idx_accounting_tasks_created_at ON accounting_tasks(created_at);

DROP TRIGGER IF EXISTS update_accounting_tasks_updated_at ON accounting_tasks;
CREATE TRIGGER update_accounting_tasks_updated_at BEFORE UPDATE ON accounting_tasks
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();


CREATE TABLE IF NOT EXISTS salaries (
  id VARCHAR(255) PRIMARY KEY,
  employee_id VARCHAR(255) NOT NULL,        -- references users.id (faculty/staff/admin); no FK in source
  employee_type employee_type_enum NOT NULL,
  base_salary DECIMAL(10,2) NOT NULL,
  allowances DECIMAL(10,2) DEFAULT 0.00,
  deductions DECIMAL(10,2) DEFAULT 0.00,
  net_salary DECIMAL(10,2) NOT NULL,
  payment_frequency payment_frequency_enum DEFAULT 'monthly',
  bank_account VARCHAR(255),
  bank_name VARCHAR(255),
  tax_id VARCHAR(100),
  start_date DATE NOT NULL,
  end_date DATE,
  status salary_status_enum DEFAULT 'active',
  notes TEXT,
  created_by VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);
